\",\n      \"11.10-g\",\n      \"11.10-k\"\n    ],\n    \"FedRAMP-Low-Revision-4\": [\n      \"ac-3\",\n      \"ac-17\",\n      \"cm-2\",\n      \"sc-7\"\n    ],\n    \"NIST-800-53-Revision-4\": [\n      \"ac_3\",\n      \"ac_4\",\n      \"ac_6\",\n      \"ac_21\",\n      \"sc_7_3\",\n      \"sc_7\"\n    ],\n    \"NIST-800-53-Revision-5\": [\n      \"ac_2_6\",\n      \"ac_3\",\n      \"ac_3_7\",\n      \"ac_4_21\",\n      \"ac_6\",\n      \"ac_17_b\",\n      \"ac_17_1\",\n      \"ac_17_4_a\",\n      \"ac_17_9\",\n      \"ac_17_10\",\n      \"cm_6_a\",\n      \"cm_9_b\",\n      \"mp_2\",\n      \"sc_7_2\",\n      \"sc_7_3\",\n      \"sc_7_7\",\n      \"sc_7_9_a\",\n      \"sc_7_11\",\n      \"sc_7_12\",\n      \"sc_7_16\",\n      \"sc_7_20\",\n      \"sc_7_21\",\n      \"sc_7_24_b\",\n      \"sc_7_25\",\n      \"sc_7_26\",\n      \"sc_7_27\",\n      \"sc_7_28\",\n      \"sc_7_a\",\n      \"sc_7_b\",\n      \"sc_7_c\",\n      \"sc_25\"\n    ],\n    \"KISA-ISMS-P-2023-korean\": [\n      \"2.6.1\",\n      \"2.6.2\",\n      \"2.10.2\"\n    ],\n    \"NIST-800-171-Revision-2\": [\n      \"3_1_1\",\n      \"3_1_2\",\n      \"3_1_3\",\n      \"3_3_8\",\n      \"3_4_6\",\n      \"3_13_2\",\n      \"3_13_5\"\n    ],\n    \"FedRamp-Moderate-Revision-4\": [\n      \"ac-3\",\n      \"ac-4\",\n      \"ac-6\",\n      \"ac-17-1\",\n      \"ac-21-b\",\n      \"cm-2\",\n      \"sc-4\",\n      \"sc-7-3\",\n      \"sc-7\"\n    ],\n    \"RBI-Cyber-Security-Framework\": [\n      \"annex_i_1_3\"\n    ],\n    \"AWS-AI-Security-Framework-1.0\": [\n      \"AISF-DATA-04\"\n    ],\n    \"AWS-Account-Security-Onboarding\": [\n      \"S3 Block Public Access\"\n    ],\n    \"AWS-Foundational-Technical-Review\": [\n      \"S3-001\"\n    ],\n    \"AWS-Audit-Manager-Control-Tower-Guardrails\": [\n      \"4.1.1\"\n    ],\n    \"AWS-Well-Architected-Framework-Security-Pillar\": [\n      \"SEC03-BP07\"\n    ]\n  },\n  \"remediation\": \"Enforce defense in depth: enable **S3 Block Public Access** at org/account and bucket levels (`BlockPublicAcls`, `IgnorePublicAcls`, `BlockPublicPolicy`, `RestrictPublicBuckets`). Apply **least privilege** with explicit principals; avoid ACLs via Object Ownership. Use private access patterns (e.g., CloudFront OAC or presigned URLs) and monitor with analyzers.\",\n  \"remediation_url\": \"https://hub.prowler.com/check/s3_bucket_public_access\",\n  \"risk_details\": \"Publicly accessible buckets jeopardize **confidentiality** through unauthenticated reads, **integrity** through write or ACL changes, and **availability** via object deletion or overwrite. Attackers can mass-exfiltrate data, host malware, or pivot after discovering secrets stored in objects.\",\n  \"referencias\": [\n    {\n      \"title\": \"Remediation\",\n      \"url\": \"https://hub.prowler.com/check/s3_bucket_public_access\"\n    }\n  ]\n}', '2026-08-26 15:43:22', 'prowler_web', '2026-08-26 15:43:22', 1),
