,\n      \"ac_17_2\",\n      \"ac_24_1\",\n      \"au_9_3\",\n      \"ca_9_b\",\n      \"cm_6_a\",\n      \"cm_9_b\",\n      \"ia_5_1_c\",\n      \"pm_11_b\",\n      \"pm_17_b\",\n      \"sc_7_4_b\",\n      \"sc_7_4_g\",\n      \"sc_7_5\",\n      \"sc_8\",\n      \"sc_8_1\",\n      \"sc_8_2\",\n      \"sc_8_3\",\n      \"sc_8_4\",\n      \"sc_8_5\",\n      \"sc_13_a\",\n      \"sc_16_1\",\n      \"sc_23\",\n      \"si_1_a_2\"\n    ],\n    \"ProwlerThreatScore-1.0\": [\n      \"4.1.1\"\n    ],\n    \"KISA-ISMS-P-2023-korean\": [\n      \"2.7.1\",\n      \"2.10.2\"\n    ],\n    \"NIST-800-171-Revision-2\": [\n      \"3_1_13\",\n      \"3_5_10\",\n      \"3_13_1\",\n      \"3_13_5\",\n      \"3_13_8\",\n      \"3_13_11\",\n      \"3_13_16\"\n    ],\n    \"FedRAMP-20x-KSI-Low-25.05C\": [\n      \"ksi-svc\"\n    ],\n    \"FedRamp-Moderate-Revision-4\": [\n      \"ac-17-2\",\n      \"sc-7\",\n      \"sc-8-1\",\n      \"sc-8\",\n      \"sc-23\"\n    ],\n    \"RBI-Cyber-Security-Framework\": [\n      \"annex_i_1_3\"\n    ],\n    \"AWS-AI-Security-Framework-1.0\": [\n      \"AISF-INFRA-06\",\n      \"AISF-DATA-04\"\n    ],\n    \"AWS-Foundational-Technical-Review\": [\n      \"S3-001\"\n    ],\n    \"AWS-Foundational-Security-Best-Practices\": [\n      \"S3.5\"\n    ],\n    \"AWS-Well-Architected-Framework-Security-Pillar\": [\n      \"SEC09-BP02\"\n    ]\n  },\n  \"remediation\": \"Enforce **HTTPS-only** access with a bucket policy that denies requests when `aws:SecureTransport=false`.\\n\\nPrefer **private access** (VPC endpoints or CloudFront with TLS), avoid S3 website endpoints, apply **least privilege**, use short-lived HTTPS **pre-signed URLs**, and monitor logs for insecure access attempts.\",\n  \"remediation_url\": \"https://hub.prowler.com/check/s3_bucket_secure_transport_policy\",\n  \"risk_details\": \"HTTP access exposes object data and auth details to **eavesdropping** and **man-in-the-middle** attacks. Captured **pre-signed URLs** can be replayed to exfiltrate data. Traffic can be intercepted or altered, undermining **confidentiality** and **integrity** of S3 content.\",\n  \"referencias\": [\n    {\n      \"title\": \"Remediation\",\n      \"url\": \"https://hub.prowler.com/check/s3_bucket_secure_transport_policy\"\n    }\n  ]\n}', '2026-08-26 15:43:22', 'prowler_web', '2026-08-26 15:43:22', 1);
