INSERT INTO `findings` (`id`, `proyecto_id`, `usuario_id`, `cloud_ejecucion_id`, `security_rules_id`, `check_id`, `provider`, `service`, `resource_id`, `region`, `severidad_id`, `estados_findings_id`, `finding_comment`, `verificado`, `inventory_data`, `referencias_data`, `detectado`, `herramienta`, `actualizacion`, `estado_id`) VALUES
(582, 20, 1, NULL, 576, 'securityhub_delegated_admin_enabled_all_regions', 'aws', 'securityhub', 'arn:aws:securityhub:ap-northeast-1:601227218666:hub/unknown', 'ap-northeast-1', 3, 1, NULL, 'NO', '{\n  \"status_code\": \"FAIL\",\n  \"account_id\": \"601227218666\"\n}', '{\n  \"compliance\": {\n    \"standards\": [],\n    \"requirements\": [],\n    \"control\": \"\"\n  },\n  \"remediation\": \"Configure a **delegated administrator** for AWS Security Hub via AWS Organizations. Enable Security Hub in **all opted-in regions** and turn on **auto-enable** so new member accounts are automatically enrolled. This ensures uniform security posture monitoring across the entire organization.\",\n  \"remediation_url\": \"https://hub.prowler.com/check/securityhub_delegated_admin_enabled_all_regions\",\n  \"risk_details\": \"Without org-wide **AWS Security Hub** configuration, findings can be aggregated inconsistently, delegated admin may be missing in some regions, and new accounts will not be auto-enrolled. This fragments **security posture visibility**, delays **incident response**, and lets misconfigurations and compliance drift go undetected across the organization.\",\n  \"referencias\": [\n    {\n      \"title\": \"Remediation\",\n      \"url\": \"https://hub.prowler.com/check/securityhub_delegated_admin_enabled_all_regions\"\n    }\n  ]\n}', '2026-08-26 15:43:22', 'prowler_web', '2026-08-26 15:43:22', 1),
